package witchinggadgets;
import net.minecraft.client.*;
import net.minecraft.core.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.level.block.Blocks;
public final class Port3Audit {
    static final String[] CAPES={"cloak","spectral_mantle","cloak_of_voluminous_pockets","wolven_cloak","mantle_of_the_raven"};
    static void tick(int phase,int offset){var mc=Minecraft.getInstance();var server=mc.getSingleplayerServer();
        if(phase==0){if(offset==0){mc.setScreen(null);mc.options.hideGui=true;mc.options.setCameraType(CameraType.FIRST_PERSON);server.execute(()->{var l=server.overworld();l.setBlockAndUpdate(new BlockPos(-3,64,0),Content.block("spinning_wheel").defaultBlockState());var wheel=(MachineEntity)l.getBlockEntity(new BlockPos(-3,64,0));for(int slot=0;slot<4;slot++)wheel.items.setStackInSlot(slot,new ItemStack(Items.STRING,8));wheel.sync();for(int i=0;i<3;i++){var p=new BlockPos(i*2,64,-8);l.setBlockAndUpdate(p,Content.block("rose_vines").defaultBlockState());var m=(MachineEntity)l.getBlockEntity(p);m.progress=i==0?0:i==1?3:5;m.sync();l.setBlockAndUpdate(p.north(),Blocks.STONE_BRICKS.defaultBlockState());l.setBlockAndUpdate(p.above().north(),Blocks.STONE_BRICKS.defaultBlockState());l.setBlockAndUpdate(p.above(),Content.block("rose_vines").defaultBlockState());m=(MachineEntity)l.getBlockEntity(p.above());m.progress=5;m.sync();}var player=server.getPlayerList().getPlayers().getFirst();player.closeContainer();player.connection.teleport(2,66,-3,180,28);});}if(offset==23)VisualAuditClient.shot("20-rose-branches-and-bounds");}
        else if(phase>=1&&phase<=3){String[] names={"spinning_wheel","cutting_table","label_library"};int[] xs={-3,3,15};if(offset==0){mc.player.closeContainer();server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();p.connection.teleport(xs[phase-1],64,2,180,20);var m=(MachineEntity)server.overworld().getBlockEntity(new BlockPos(xs[phase-1],64,0));m.use(p,InteractionHand.MAIN_HAND);});}if(offset==23){if(!(mc.screen instanceof MachineScreen))throw new IllegalStateException("Original GUI did not open: "+names[phase-1]);VisualAuditClient.shot((20+phase)+"-gui-"+names[phase-1]);}}
        else if(phase>=4&&phase<=7){String[] names={"bag_of_tricks","voidlinked_bag","cloak_of_voluminous_pockets","primordial_gauntlet"};if(offset==0){mc.player.closeContainer();server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();var s=Content.stack(names[phase-4]);p.setItemInHand(InteractionHand.MAIN_HAND,s);BagItem.open(p,s,phase==6?27:phase==7?9:18);});}if(offset==23){if(!(mc.screen instanceof StorageScreen))throw new IllegalStateException("Storage screen failed");VisualAuditClient.shot((20+phase)+"-gui-"+names[phase-4]);}}
        else if(phase==8||phase==9){if(offset==0){mc.player.closeContainer();mc.setScreen(new thaumcraft.client.research.ResearchPageScreen(thaumcraft.research.ResearchCategories.getResearch(phase==8?"PURECINNABAR":"METALLURGICPERFECTION_CLUSTERS"),0));}if(offset==23)VisualAuditClient.shot((20+phase)+"-book-full-russian");}
        else if(phase>=10&&phase<=14){if(offset==0){mc.setScreen(null);mc.options.hideGui=true;mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();p.closeContainer();for(var slot:EquipmentSlot.values())if(slot.isArmor())p.setItemSlot(slot,ItemStack.EMPTY);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).ifPresent(inv->{for(var handler:inv.getCurios().values())for(int s=0;s<handler.getStacks().getSlots();s++)handler.getStacks().setStackInSlot(s,ItemStack.EMPTY);inv.getStacksHandler("back").ifPresent(h->h.getStacks().setStackInSlot(0,Content.stack(CAPES[phase-10])));});p.connection.teleport(6,64,5,0,0);});}if(offset==23)VisualAuditClient.shot((20+phase)+"-cape-"+CAPES[phase-10]);}
        else if(phase==15){if(offset==0){mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();p.setItemInHand(InteractionHand.MAIN_HAND,Content.stack("primordial_gauntlet"));p.setItemInHand(InteractionHand.OFF_HAND,Content.stack("primordial_gauntlet"));});}if(offset==23)VisualAuditClient.shot("35-manopla-on-both-arms");}
        else if(phase==16){if(offset==0)server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();for(var r:thaumcraft.research.ResearchCategories.allResearch())thaumcraft.research.ResearchManager.complete(p,r.key(),false);});if(offset==10){try{var field=thaumcraft.client.research.ResearchBrowserScreen.class.getDeclaredField("selectedCategory");field.setAccessible(true);field.set(null,Research.CATEGORY);}catch(ReflectiveOperationException e){throw new IllegalStateException(e);}thaumcraft.client.research.ResearchBrowserScreen.lastX=-10;thaumcraft.client.research.ResearchBrowserScreen.lastY=2;mc.setScreen(new thaumcraft.client.research.ResearchBrowserScreen());}if(offset==23)VisualAuditClient.shot("36-research-original-icons");}
        else if(phase==17||phase==18){if(offset==0){mc.setScreen(null);mc.options.hideGui=true;mc.options.setCameraType(CameraType.FIRST_PERSON);server.execute(()->{var p=server.getPlayerList().getPlayers().getFirst();p.closeContainer();p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);p.connection.teleport(phase==17?.5:12.5,63.8,phase==17?-2.5:2.5,180,20);});}if(offset==8||offset==23)VisualAuditClient.shot((phase==17?"37-focus-rotation-":"38-bellows-motion-")+offset);}
        else{System.out.println("WG_PORT3_AUDIT: original machine/storage GUIs, research text/icons, 5 vanilla cape variants, Manopla arm attachment and rose branches rendered");mc.stop();}
    }
}
